#!/usr/bin/env bash
set -e

echo '=== شروع به‌روزرسانی نهایی و قطعی DocuShift روی سرور ==='

# ۱. دانلود فونت استاندارد وزیرمتن
echo '۱. به‌روزرسانی فونت Vazirmatn...'
curl -sL https://raw.githubusercontent.com/rastikerdar/vazirmatn/master/fonts/ttf/Vazirmatn-Regular.ttf -o server/assets/fonts/persian-font.ttf || true

# ۲. به‌روزرسانی موتور حروف فارسی
echo '۲. به‌روزرسانی موتور حروف فارسی...'
cat << 'PERS' > server/processors/persianShaper.ts
export function sanitizePersianSymbols(raw: string): string {
  if (!raw) return '';
  return raw
    .replace(/[​‍‎‏﻿]/g, '')
    .replace(/[«»“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[••●■▪◦∙]/g, '-')
    .replace(/[—–]/g, '-')
    .replace(/\|/g, '-')
    .replace(/[⚠️⚠]/g, '[!]');
}

export interface BidiSegment {
  text: string;
  isRtl: boolean;
}

export function segmentBidiText(line: string): BidiSegment[] {
  if (!line) return [];
  const clean = sanitizePersianSymbols(line);
  const regex = /[؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿‌]+|[^؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿‌]+/g;
  const matches = clean.match(regex) || [];
  
  return matches.map((token) => ({
    text: token,
    isRtl: /[؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿]/.test(token),
  }));
}
PERS

# ۳. استقرار قطعی پردازنده PDF
echo '۳. استقرار پردازنده PDF...'
base64 -d << 'PDFB64' > server/processors/pdfProcessor.ts

PDFB64

# ۴. کامپایل نهایی و ری‌استارت
echo '۴. بیلد مجدد و ری‌استارت...'
npm run build
pm2 restart docushift || true

echo '=== به‌روزرسانی با موفقیت کامل به پایان رسید! ==='
